BEGIN;
-- Preserve all configured amounts. The legacy lifetime_cents column now stores the weekly cap.
COMMENT ON COLUMN public.ct_demo_card_tiers.lifetime_cents IS 'Weekly per-player cap in euro cents; NULL means unlimited. Monday 00:00 Europe/Paris. Legacy column name retained for RPC compatibility.';
CREATE OR REPLACE FUNCTION public.ct_diamond_store() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('version',s.version,'eur_per_diamond',coalesce(t.eur_per_diamond,s.eur_per_diamond)::text,'purchases_enabled',s.purchases_enabled AND coalesce(t.purchases_enabled,false) AND public.ct_circle_member(auth.uid()),'wallets_frozen',s.wallets_frozen,'market_enabled',s.market_enabled,'max_purchase_cents',CASE WHEN t.id='cosmic' THEN t.max_purchase_cents ELSE least(s.max_purchase_cents,t.max_purchase_cents) END,'min_purchase_cents',coalesce(t.min_purchase_cents,1),'daily_user_cents',CASE WHEN t.id='cosmic' THEN t.daily_cents ELSE least(s.daily_user_cents,t.daily_cents) END,'lifetime_cents',NULL,'weekly_cents',t.lifetime_cents,'week_starts_at',(date_trunc('week',now() AT TIME ZONE 'Europe/Paris') AT TIME ZONE 'Europe/Paris'),'week_resets_at',((date_trunc('week',now() AT TIME ZONE 'Europe/Paris')+interval '1 week') AT TIME ZONE 'Europe/Paris'),'spent_week_cents',(SELECT coalesce(sum(total_cents),0) FROM public.ct_simulated_diamond_purchases WHERE user_id=auth.uid() AND created_at >= (date_trunc('week',now() AT TIME ZONE 'Europe/Paris') AT TIME ZONE 'Europe/Paris')),'spent_total_cents',(SELECT coalesce(sum(total_cents),0) FROM public.ct_simulated_diamond_purchases WHERE user_id=auth.uid()),'total_cap_reached',s.total_cap_cents IS NOT NULL AND(SELECT coalesce(sum(total_cents),0) FROM public.ct_simulated_diamond_purchases)>=s.total_cap_cents,'spent_today_cents',(SELECT coalesce(sum(total_cents),0) FROM public.ct_simulated_diamond_purchases WHERE user_id=auth.uid() AND created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),'card_tier',t.id,'card_name',t.name,'simulated',true) FROM public.ct_market_settings s LEFT JOIN public.ct_demo_cards c ON c.user_id=auth.uid() LEFT JOIN public.ct_demo_card_tiers t ON t.id=c.tier_id WHERE s.id;
$$;
CREATE OR REPLACE FUNCTION public.ct_buy_diamonds_simulated(p_operation_id uuid,p_quantity integer,p_expected_version bigint,p_expected_total_cents bigint,p_demo_method text DEFAULT 'demo_card') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid;r jsonb;q jsonb:=jsonb_build_object('kind','simulated_diamond_purchase','quantity',p_quantity,'version',p_expected_version,'total_cents',p_expected_total_cents,'demo_method',p_demo_method);s public.ct_market_settings;t public.ct_demo_card_tiers;c public.ct_demo_cards;v_rate numeric;v_cents bigint;v_spent bigint;v_total bigint;v_lifetime bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(173,8);u:=public.ct_lock_wallet();r:=public.ct_replay(u,p_operation_id,q);IF r IS NOT NULL THEN RETURN r;END IF;PERFORM public.ct_check_rate(u);
 SELECT * INTO s FROM public.ct_market_settings WHERE id;SELECT * INTO c FROM public.ct_demo_cards WHERE user_id=u;SELECT * INTO t FROM public.ct_demo_card_tiers WHERE id=c.tier_id;
 IF NOT public.ct_circle_member(u) THEN RAISE EXCEPTION 'Une carte active du cercle fermé est requise';END IF;
 IF NOT s.purchases_enabled OR s.wallets_frozen OR NOT t.purchases_enabled THEN RAISE EXCEPTION 'Les achats fictifs de diamants sont suspendus';END IF;
 IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 10000 OR p_demo_method IS DISTINCT FROM 'demo_card' THEN RAISE EXCEPTION 'Simulation invalide : carte de démonstration uniquement';END IF;
 v_rate:=coalesce(t.eur_per_diamond,s.eur_per_diamond);v_cents:=round(p_quantity*v_rate*100)::bigint;
 IF p_expected_version IS DISTINCT FROM s.version OR p_expected_total_cents IS DISTINCT FROM v_cents THEN RAISE EXCEPTION 'Le tarif a changé. Actualisez et confirmez le nouveau total.';END IF;
 SELECT coalesce(sum(total_cents) FILTER(WHERE created_at >= (date_trunc('week',now() AT TIME ZONE 'Europe/Paris') AT TIME ZONE 'Europe/Paris')),0),coalesce(sum(total_cents) FILTER(WHERE created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0) INTO v_lifetime,v_spent FROM public.ct_simulated_diamond_purchases WHERE user_id=u;
 SELECT coalesce(sum(total_cents),0) INTO v_total FROM public.ct_simulated_diamond_purchases;
 IF v_cents<t.min_purchase_cents OR v_cents>(CASE WHEN t.id='cosmic' THEN t.max_purchase_cents ELSE least(s.max_purchase_cents,t.max_purchase_cents) END) OR v_spent+v_cents>(CASE WHEN t.id='cosmic' THEN t.daily_cents ELSE least(s.daily_user_cents,t.daily_cents) END) OR(t.lifetime_cents IS NOT NULL AND v_lifetime+v_cents>t.lifetime_cents) OR(s.total_cap_cents IS NOT NULL AND v_total+v_cents>s.total_cap_cents) THEN RAISE EXCEPTION 'Plafond de simulation ou montant minimum de la carte atteint';END IF;
 INSERT INTO public.ct_simulated_diamond_purchases(user_id,operation_id,quantity,unit_eur,total_cents,settings_version,demo_method,card_tier,card_version) VALUES(u,p_operation_id,p_quantity,v_rate,v_cents,s.version,p_demo_method,t.id,t.version);
 PERFORM public.ct_post_diamond(u,p_quantity,'simulated_purchase','sim-purchase:'||p_operation_id::text);r:=jsonb_build_object('ok',true,'simulated',true,'total_cents',v_cents,'diamonds',p_quantity,'card_tier',t.id);
 INSERT INTO public.ct_operations(user_id,operation_id,request,result) VALUES(u,p_operation_id,q,r);RETURN r;
END $$;
CREATE OR REPLACE FUNCTION public.ct_admin_cards(p_search text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN IF NOT public.ct_is_admin() THEN RAISE EXCEPTION 'Administrator required' USING ERRCODE='42501';END IF;
 IF length(coalesce(p_search,''))>50 THEN RAISE EXCEPTION 'Recherche trop longue';END IF;
 RETURN jsonb_build_object('week_resets_at',((date_trunc('week',now() AT TIME ZONE 'Europe/Paris')+interval '1 week') AT TIME ZONE 'Europe/Paris'),'tiers',(SELECT jsonb_agg(to_jsonb(t)||jsonb_build_object('eur_per_diamond',eur_per_diamond::text) ORDER BY rank) FROM public.ct_demo_card_tiers t),'players',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM(SELECT p.id,p.username,c.tier_id,c.version,c.suspended,(SELECT coalesce(sum(total_cents),0) FROM public.ct_simulated_diamond_purchases WHERE user_id=p.id) spent_total_cents,(SELECT coalesce(sum(total_cents),0) FROM public.ct_simulated_diamond_purchases WHERE user_id=p.id AND created_at >= (date_trunc('week',now() AT TIME ZONE 'Europe/Paris') AT TIME ZONE 'Europe/Paris')) spent_week_cents FROM public.ct_profiles p LEFT JOIN public.ct_demo_cards c ON c.user_id=p.id WHERE NOT p.is_bot AND position(lower(coalesce(p_search,'')) IN lower(p.username))>0 ORDER BY p.username LIMIT 30)x),'[]'::jsonb));END $$;
CREATE OR REPLACE FUNCTION public.ct_circle_access() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('member',public.ct_circle_member(auth.uid()),'week_resets_at',((date_trunc('week',now() AT TIME ZONE 'Europe/Paris')+interval '1 week') AT TIME ZONE 'Europe/Paris'),'card',(SELECT to_jsonb(c)||jsonb_build_object('name',t.name,'active',t.active) FROM public.ct_demo_cards c JOIN public.ct_demo_card_tiers t ON t.id=c.tier_id WHERE c.user_id=auth.uid()),'application',(SELECT to_jsonb(a) FROM public.ct_circle_applications a WHERE user_id=auth.uid() ORDER BY created_at DESC,id DESC LIMIT 1),'tiers',(SELECT jsonb_agg(to_jsonb(t)||jsonb_build_object('eur_per_diamond',t.eur_per_diamond::text) ORDER BY rank) FROM public.ct_demo_card_tiers t));
$$;

UPDATE public.ct_market_settings SET version=version+1 WHERE id;
COMMIT;
